/* 循词：所有成绩和词汇状态均来自用户的明确操作。 */
(() => {
  'use strict';
  const E = window.IELTS_ENGINE;
  const S = window.IELTS_SYNC;
  let cloudClient=null, cloudStatus={status:"loading",message:"正在连接",user:null}, cloudLessons=[], wordCards=[];
  let authClient=null, authStatus={status:'loading',enabled:null,authenticated:false,user:null},authBootReady=false;
  const KEY = 'xunci.ielts7.v1';
  const $ = (s, root = document) => root.querySelector(s);
  const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const norm = x => String(x || '').trim().toLowerCase().replace(/\s+/g,' ');
  let date = E.today();
  const emptyReading=()=>({assignments:{},results:{},completed:{},excluded:[]});
  let storageProblem = '';
  let state;
  try { state = JSON.parse(localStorage.getItem(KEY) || 'null'); if(state){ E.makeBackup(state.records,{lastExcel:state.lastExcel,readingState:state.readingState}); if(!Array.isArray(state.customLessons||[]))throw Error('课程结构无效'); } } catch { state=null; storageProblem = '已保存进度未通过校验；请在数据与设置中恢复有效备份。当前显示初始词库。'; }
  if (!state || !Array.isArray(state.records)) state = { records: E.seed(window.VOCAB_HISTORY || [], window.VOCAB_NEW || []), lastExcel:E.today(), readingState:{assignments:{},results:{},completed:{},excluded:[]}, customLessons:[] };
  state.readingState ||= {assignments:{},results:{},completed:{},excluded:[]};
  ['assignments','results','completed'].forEach(k=>state.readingState[k] ||= {});
  state.readingState.excluded ||= [];
  state.customLessons ||= [];
  state.preferences=S.validatePreferences(state.preferences);
  const readingDrafts={};
  let recallDirection='en-zh';
  let calendarOffset=0, librarySort='priority', libraryLetter='', reviewExercise=null;
  let libraryLevel='all', libraryQuery='', libraryPage=0, reviewQueue=[], reviewIndex=0, reviewAnswer='', currentLessonId=null, showAnswers=false, intakeStage=null, intakeSource=null;
  const main=$('#main');
  function save(localOnly=false){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageProblem='本机保存失败，请下载备份。';toast(storageProblem);}if(!localOnly)cloudClient?.queue();updateSidebar();}
  function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
  function download(data,name,type){const blob=data instanceof Blob?data:new Blob([data],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
  function showModal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();}
  function closeModal(){$('#modal').close();}
  $('.dialog-close').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal();});
  const lessonPool=()=>[...new Map([...(window.READING_LESSONS||[]),...cloudLessons,...state.customLessons].map(l=>[l.id,l])).values()];
  function dailyLesson(){
    const all=lessonPool(),rs=state.readingState;
    if(rs.assignments[date])return all.find(l=>l.id===rs.assignments[date])||null;
    const used=new Set(Object.values(rs.assignments));
    const available=all.filter(l=>!used.has(l.id)&&!rs.excluded.includes(l.url)&&(!l.learningDate||l.learningDate<=date));
    const weakness=weaknesses();
    const next=available.map((l,i)=>({l,i,score:(l.learningDate===date?10:0)+weakness.reduce((n,w)=>n+(l.focus.includes(w)?1:0),0)})).sort((a,b)=>b.score-a.score||a.i-b.i)[0]?.l;
    if(next){rs.assignments[date]=next.id;save();}return next||null;
  }
  function weaknesses(){const events=Object.values(state.readingState.results).sort((a,b)=>b.submittedAt.localeCompare(a.submittedAt));const recent=events[0];if(!recent)return [];const lesson=lessonPool().find(l=>l.id===recent.lessonId);if(!lesson)return [];const weak=new Set();for(const q of lesson.questions){if(norm(recent.answers[q.id])===norm(q.answer))continue;if(q.type==='tfng')weak.add('FALSE / NOT GIVEN');if(/数字|单位|倍|变量|比例/.test(q.trap+' '+q.explanation))weak.add('数字');if(/修饰|范围|并列|条件|限定/.test(q.trap+' '+q.explanation))weak.add('限定');}return [...weak];}
  const dayNo=()=>Object.keys(state.readingState.assignments).sort().indexOf(date)+1;
  const findRecord=word=>state.records.find(r=>E.normalizeWord(r.word)===E.normalizeWord(word));
  const expEn=r=>r.example?.en||r.exampleEn||'';
  const expZh=r=>r.example?.zh||r.exampleZh||'';
  const batch=r=>r.batch||r.origins?.[0]?.batch||'自主提交';
  const reviewBatch=r=>batch(r)+(r.group?' · '+r.group:'');
  const stageLabel=r=>r.level==='B'?'认读与理解':r.forceTeaching?'错词重新教学':r.contacts<2?'教学与理解':r.contacts===2?'有提示的主动回忆':'搭配与语境输出';
  const errors=r=>r.errors?.some(x=>!x.resolved);
  function heading(eyebrow,title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
  const pairs=arr=>(arr||[]).map(p=>`<div class="bilingual"><p>${esc(p.en)}</p><p class="zh">${esc(p.zh)}</p></div>`).join('');
  function week(){
    const anchor=E.addDays(date,calendarOffset*7),d=new Date(anchor+'T12:00:00Z'),start=E.addDays(anchor,-((d.getUTCDay()+6)%7)),names=['一','二','三','四','五','六','日'];
    const activity=new Set(state.records.flatMap(r=>(r.reviewHistory||[]).map(h=>h.date)));
    return `<div class="weekstrip"><div class="week-lead"><strong>学习日历</strong><small>${start.slice(5)} — ${E.addDays(start,6).slice(5)}</small></div><button class="calendar-arrow" data-action="calendar-prev" aria-label="上一周">‹</button><div class="weekdays">${names.map((n,i)=>{const day=E.addDays(start,i),l=state.readingState.assignments[day];return `<button class="week-day ${day===date?'today':''} ${activity.has(day)||l?'done':''}" data-action="calendar-day" data-date="${day}"><span>周${n}</span><strong>${+day.slice(-2)}</strong><i></i></button>`;}).join('')}</div><button class="calendar-arrow" data-action="calendar-next" aria-label="下一周" ${calendarOffset>=0?'disabled':''}>›</button></div>`;
  }
  function groupedDue(){const map=new Map();E.due(state.records,date).forEach(r=>{const k=reviewBatch(r);if(!map.has(k))map.set(k,[]);map.get(k).push(r);});return [...map.entries()];}
  function batchRows(limit=99){const groups=groupedDue().slice(0,limit);return groups.length?groups.map(([b,words])=>{
    const exact=words.filter(r=>r.nextReview===date).length;
    return `<div class="batch-row"><div class="batch-icon">↻</div><div class="batch-info"><strong>${esc(b)}<span class="chip ${exact?'':'amber'}">${exact?'今日到期':'待补复习'}</span></strong><p>第 ${Math.min(...words.map(w=>w.contacts+1))} 次起 · ${words.some(r=>errors(r))?'错词教学':words.every(r=>r.contacts<2)?'教学与识别':'回忆与使用'} · ${esc(words.slice(0,3).map(w=>w.word).join(' / '))}</p></div><div class="batch-right"><strong>${words.length} 词</strong><small>优先分批学习</small></div><button class="batch-arrow" data-action="start-batch" data-batch="${esc(b)}" aria-label="开始 ${esc(b)} 复习">→</button></div>`;
  }).join(''):`<div class="empty"><h2>今天没有到期批次</h2><p>可以继续精读，或选择词库中的一个主题。</p></div>`;}
  function dashboard(){
    const due=E.due(state.records,date),done=state.records.filter(r=>r.reviewHistory?.some(h=>h.date===date)).length,l=dailyLesson(),limit=E.studyQueue(state.records,date,state.preferences).length;
    main.innerHTML=heading('TODAY','今日学习',`${date} · 今日先完成一组词汇，再读一篇文章。`)+week()+
      `<div class="dashboard-grid"><section class="hero-study"><div class="eyebrow">VOCABULARY SESSION</div><h2>${limit?'这一组练习 '+limit+' 个词':due.length?'今天的新词量已完成':'今天的词汇复习已完成'}</h2><p>${due.length?`${due.length} 个待学习 · 每天最多 ${state.preferences.dailyNewLimit} 个新词`:'继续精读，或到词库选择你想巩固的表达。'}</p><div class="session-tags"><span>英式发音</span><span>词义识别</span><span>搭配与使用</span></div>${limit?'<button class="button" data-action="start-review">开始练习 →</button>':'<a class="button" href="#library">打开词库 →</a>'}<div class="hero-motif" aria-hidden="true"><span>01</span><span>03</span><span>07</span><span>14</span><i></i></div></section>
      <section class="reading-card"><div class="eyebrow">DAILY READING</div><div class="topic">${l?esc(l.topic):'课程档案'}</div><h3>${l?esc(l.title):'选择一篇文章开始阅读'}</h3><p class="title-zh">${l?esc(l.titleZh||l.article?.titleZh||''):''}</p><div class="source">${l?`${esc(l.source)} · ${esc(l.published)}`:''}</div><div class="reading-meta"><span>首读 ${l?.minutes||'—'} 分钟</span><span>${esc(l?.difficulty||'IELTS Reading')}</span></div><a class="button outline" href="#reading">阅读与练习 →</a></section></div>
      <div class="stats"><div class="stat"><div class="stat-label">词库</div><div class="stat-number">${state.records.length}<small>词 / 短语</small></div><p>A ${state.records.filter(r=>r.level==='A').length} · B ${state.records.filter(r=>r.level==='B').length}</p></div><div class="stat"><div class="stat-label">今天已学</div><div class="stat-number">${done}<small>词</small></div><p>查看学习日历可回访</p></div><div class="stat"><div class="stat-label">今日精读</div><div class="stat-number">${l&&state.readingState.completed[l.id]?1:0}<small>/ 1 篇</small></div><p>${l?esc(l.topic):'选择课程'}</p></div><div class="stat"><div class="stat-label">课程档案</div><div class="stat-number">${lessonPool().length}<small>篇</small></div><p>文章与练习保留在档案中</p></div></div>
      <div class="section-head"><h2>待复习批次</h2><a href="#review">查看全部 →</a></div><div class="review-list">${batchRows(3)}</div>`;
  }
  function startReview(selectedBatch){const selected=selectedBatch?state.records.filter(r=>reviewBatch(r)===selectedBatch).map(r=>r.id):null;reviewQueue=E.studyQueue(state.records,date,state.preferences,selected);reviewIndex=0;reviewAnswer='';reviewExercise=null;location.hash='review';review();if(!reviewQueue.length)toast('今日新词量已完成，可继续精读或回看词卡。');}
  function teachingContent(r){return `<div class="meaning">${esc(r.meaning||'释义待补充')}</div><div class="word-pos">${esc(r.pos)}</div>${r.needsContent?'<div class="notice warn">这个新词尚无完整教案。先补充词义、IPA 和例句，再确认学习。</div>':''}<div class="detail-grid"><div class="detail-block"><h4>构词 / 理解提示</h4><p>${esc(r.memory||r.family||'通过常用搭配与具体例句理解；不编造词源。')}</p><h4 class="mt">保留词族</h4><p>${esc(r.family||'待补充')}</p></div><div class="detail-block"><h4>常用搭配</h4>${(r.collocations||[]).map(c=>`<p>${esc(c.en)}<br><span class="muted">${esc(c.zh)}</span></p>`).join('')||'<p class="muted">待补充</p>'}</div></div><div class="detail-block"><h4>IELTS 同义替换与区别</h4><p>${esc(r.synonyms||'待补充')}</p></div>${expEn(r)?`<div class="example"><p>${esc(expEn(r))}</p><p class="zh">${esc(expZh(r))}</p></div>`:''}<div class="safe-small">${examNotes(r)}</div>`;}
  function review(){
    if(!reviewQueue.length){const size=E.studyQueue(state.records,date,state.preferences).length;main.innerHTML=heading('VOCABULARY PRACTICE','词汇练习','选择一个批次，从词义识别逐步练到搭配和表达。',`<button class="button" data-action="start-review" ${size?'':'disabled'}>${size?'开始优先 '+size+' 词 →':'今日新词量已完成'}</button>`)+`<div class="review-list">${batchRows()}</div>`;return;}
    if(reviewIndex>=reviewQueue.length){main.innerHTML=heading('A SMALL STEP FORWARD','这组学习已完成。','这一组已保存。')+`<div class="card empty"><h2>给记忆一点休息的时间。</h2><p>本轮 ${reviewQueue.length} 词 · 可以继续下一组或开始精读</p><div class="form-row" style="justify-content:center"><button class="button" data-action="restart-review">继续下一组 →</button><a href="#today" class="button outline">返回今日学习</a></div></div>`;return;}
    const r=state.records.find(x=>x.id===reviewQueue[reviewIndex].id)||reviewQueue[reviewIndex],mode=E.mode(r);
    main.innerHTML=`<div class="review-layout">${heading('ONE WORD, ONE CONNECTION','今日词汇练习',`${esc(reviewBatch(r))} · 第 ${r.contacts+1} 次接触 · ${stageLabel(r)}`,`<button class="text-button" data-action="exit-review">返回批次</button>`)}<div class="progress-bar"><i style="width:${reviewIndex/reviewQueue.length*100}%"></i></div><article class="card study-card"><div class="study-top"><span class="level-pill ${r.level}">${r.level}</span><span class="muted">${reviewIndex+1} / ${reviewQueue.length} · 首见 ${r.firstSeen}</span></div><div class="eyebrow">${mode==='teaching'?'LEARN & UNDERSTAND':mode==='hinted'?'RECALL WITH A LITTLE HELP':'PUT IT INTO CONTEXT'}</div><h2>${mode==='hinted'&&recallDirection==='zh-en'?esc(r.meaning):esc(r.displayWord||r.word)}</h2><span class="ipa">${esc(r.ipa||'英式音标待补充')}</span><button class="audio-button" data-action="speak" data-word="${esc(r.word)}" aria-label="朗读 ${esc(r.word)}">♪</button>
    ${mode==='teaching'?teachingContent(r)+teachingInteraction(r):`<div class="notice">${mode==='hinted'?'第三次接触：可以使用首字母、IPA 和搭配提示。先尝试回忆中文义，再写出一个对应的英文表达。':'第四次起：在句子中使用这个词，留意搭配和语气。核对后由你明确标记结果。'}</div><div class="example"><p>${mode==='hinted'?(recallDirection==='en-zh'?`English → Chinese: ${esc(r.word)}`:`中文 → English: ${esc(r.meaning)}（${esc(r.word.slice(0,1))}…）`):esc(expEn(r).replace(new RegExp(r.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'ig'),'______')||`Write a sentence using ${r.word}.`)}</p><p class="zh">${mode==='hinted'?'提示搭配：'+esc(recallDirection==='en-zh'?(r.collocations?.[0]?.en||'可查看英式 IPA'):(r.collocations?.[0]?.zh||'可查看首字母与英式 IPA')):esc(expZh(r))}</p></div>${mode==='hinted'?'<div class="tabs"><button class="'+(recallDirection==='en-zh'?'active':'')+'" data-action="recall-en-zh">英 → 中</button><button class="'+(recallDirection==='zh-en'?'active':'')+'" data-action="recall-zh-en">中 → 英</button></div>':''}<label>你的实际作答<textarea id="review-answer" rows="3" placeholder="写下词义、英文表达或句子后，再核对答案">${esc(reviewAnswer)}</textarea></label><div class="form-row"><button class="button outline small" data-action="reveal-review">查看答案与讲解</button></div><div id="review-reveal" hidden>${teachingContent(r)}</div>`}
    <div class="study-footer"><span class="study-next">${mode==='teaching'?'理解 · 识别 · 练习搭配':'完成作答后核对'}</span><div class="form-row">${r.needsContent?`<button class="button" data-action="edit-word" data-id="${r.id}">补充教案</button>`:mode==='teaching'?'<button class="button" data-action="confirm-study">完成这一词 →</button>':'<button class="button danger" data-action="wrong-review">需要重学</button><button class="button" data-action="correct-review">核对后答对 →</button>'}</div></div></article><details class="review-meta"><summary>本词复习安排</summary><p>${[0,1,3,7,14,30].map(d=>`D${d} ${E.addDays(r.firstSeen,d)}`).join(' · ')}</p></details></div>`;
  }
  function recordReview(kind){const r=state.records.find(x=>x.id===reviewQueue[reviewIndex]?.id);if(!r)return;try{const answer=$('#review-answer')?.value||'';if(kind!=='studied'&&$('#review-reveal')?.hidden !== false){toast('请先核对答案与讲解。');return;}const changed=E.review(r,{kind,date,answer});state.records=state.records.map(x=>x.id===r.id?changed:x);save();reviewIndex++;reviewAnswer='';reviewExercise=null;review();if(kind==='wrong')toast('已重返教学，并加入次日 / 三日加练。');}catch(e){toast(e.message);}}
  function library(){
    const filtered=state.records.filter(r=>(libraryLevel==='all'||r.level===libraryLevel)&&(!libraryQuery||norm([r.word,r.meaning,r.family,r.synonyms,batch(r)].join(' ')).includes(norm(libraryQuery))));
    let all=filtered.filter(r=>!libraryLetter||r.word.charAt(0).toLowerCase()===libraryLetter);
    const cluster=r=>window.IELTS_EXAM_NOTES?.[r.word]?.cluster||r.group||String(r.family).split(/[ ;；]/)[0]||r.word;
    const priority=r=>(errors(r)?1000:0)+(r.repeats||0)*100+(r.level==='A'?20:0)+(r.nextReview&&r.nextReview<=date?10:0);
    all.sort((a,b)=>librarySort==='alpha'?a.word.localeCompare(b.word):librarySort==='recent'?b.firstSeen.localeCompare(a.firstSeen)||a.word.localeCompare(b.word):librarySort==='family'?cluster(a).localeCompare(cluster(b),'zh-CN')||a.word.localeCompare(b.word):priority(b)-priority(a)||a.word.localeCompare(b.word));
    const size=16,pages=Math.max(1,Math.ceil(all.length/size));libraryPage=Math.min(libraryPage,pages-1);
    main.innerHTML=heading('VOCABULARY','我的词库','按词义、词族和同义替换整理，选择需要巩固的表达。',`<button class="button" data-action="intake">＋ 录入陌生词</button>`)+
      `<div class="toolbar"><div class="tabs">${[['all','全部'],['A','A 重点'],['B','B 认读'],['C','C 暂存']].map(([k,t])=>`<button data-action="library-filter" data-level="${k}" class="${libraryLevel===k?'active':''}">${t}</button>`).join('')}</div><label class="sort-control">排序 <select id="library-sort"><option value="priority" ${librarySort==='priority'?'selected':''}>复习优先</option><option value="alpha" ${librarySort==='alpha'?'selected':''}>字母 A–Z</option><option value="recent" ${librarySort==='recent'?'selected':''}>最近收录</option><option value="family" ${librarySort==='family'?'selected':''}>同义主题 / 词族</option></select></label><div class="search"><span>⌕</span><input id="word-search" aria-label="搜索词汇、词义或同义替换" value="${esc(libraryQuery)}" placeholder="单词、中文、词族、同义词…"></div></div>
      ${librarySort==='alpha'?`<nav class="alphabet" aria-label="按首字母定位"><button data-action="library-letter" data-letter="" class="${!libraryLetter?'active':''}">全部</button>${'abcdefghijklmnopqrstuvwxyz'.split('').map(letter=>`<button data-action="library-letter" data-letter="${letter}" class="${libraryLetter===letter?'active':''}" ${!filtered.some(r=>r.word.charAt(0).toLowerCase()===letter)?'disabled':''}>${letter.toUpperCase()}</button>`).join('')}</nav>`:''}
      <div class="table-wrap"><table><thead><tr><th>词汇 / 英式 IPA</th><th>词义与词性</th><th>分级</th><th>${librarySort==='family'?'同义主题 / 词族':'来源'}</th><th>学习阶段</th><th>复习日期</th><th></th></tr></thead><tbody>${all.slice(libraryPage*size,(libraryPage+1)*size).map(r=>`<tr><td><button class="text-button word" data-action="word-detail" data-id="${r.id}">${esc(r.displayWord||r.word)}</button><div class="ipa">${esc(r.ipa||'待补充')}</div></td><td>${esc(r.meaning||'待补充词义')}<div class="word-pos">${esc(r.pos)}</div></td><td><span class="level-pill ${r.level}">${r.level}</span></td><td><span class="muted">${esc(librarySort==='family'?cluster(r):(r.source?.title||batch(r)))}</span></td><td><span class="muted">${stageLabel(r)}</span>${r.needsContent?'<div class="chip amber">待补充词卡</div>':errors(r)?'<div class="chip amber">错词加练</div>':''}</td><td><span class="muted">${r.level==='C'?'暂不安排':r.nextReview||'本轮完成'}</span></td><td><button class="batch-arrow" data-action="word-detail" data-id="${r.id}" aria-label="查看 ${esc(r.word)}">↗</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">没有符合条件的词汇。</td></tr>'}</tbody></table></div>
      <div class="pagination"><span>${all.length} 个条目</span><div class="page-controls"><button class="button outline small" data-action="prev-page" ${libraryPage===0?'disabled':''}>←</button><label>第 <select id="library-page" aria-label="选择页码">${Array.from({length:pages},(_,i)=>`<option value="${i}" ${i===libraryPage?'selected':''}>${i+1}</option>`).join('')}</select> / ${pages} 页</label><button class="button outline small" data-action="next-page" ${libraryPage===pages-1?'disabled':''}>→</button></div></div>`;
    $('#library-sort').onchange=e=>{librarySort=e.target.value;libraryLetter='';libraryPage=0;library();};$('#library-page').onchange=e=>{libraryPage=+e.target.value;library();};
    $('#word-search').oninput=e=>{const pos=e.target.selectionStart;libraryQuery=e.target.value;libraryPage=0;library();const input=$('#word-search');input.focus();input.setSelectionRange(pos,pos);};
  }
  function wordDetail(id){
    const r=state.records.find(x=>x.id===id);if(!r)return;
    const sources=[...new Map([r.source,...(r.origins||[]).map(o=>o.source)].filter(x=>x?.title&&x?.url).map(x=>[x.url,x])).values()];
    showModal(`<div class="word-modal-head"><div class="eyebrow">${r.level==='A'?'重点词汇':r.level==='B'?'认读词汇':'暂存词汇'}</div><h2>${esc(r.displayWord||r.word)} <span class="level-pill ${r.level}">${r.level}</span></h2><span class="ipa">${esc(r.ipa)}</span><button class="audio-button" data-action="speak" data-word="${esc(r.word)}" aria-label="朗读 ${esc(r.word)}">▶</button></div>${teachingContent(r)}
      <section class="word-source"><h4>来源</h4>${sources.length?sources.map(src=>`<a href="${esc(src.url)}" target="_blank" rel="noopener noreferrer">${esc(src.title)} ↗</a><p class="muted">${esc(src.publisher||'')} ${esc(src.date||'')}</p>`).join(''):`<p>手动录入 · ${esc(batch(r))}</p>`}</section>
      <details class="review-meta"><summary>复习信息</summary><dl><div><dt>首次学习</dt><dd>${r.firstSeen}</dd></div><div><dt>最近复习</dt><dd>${r.lastReview||'尚未复习'}</dd></div><div><dt>下一次</dt><dd>${r.nextReview||'本轮完成'}</dd></div><div><dt>接触次数</dt><dd>${r.contacts}</dd></div></dl></details>
      <div class="word-modal-controls"><label>分级<select id="detail-level"><option ${r.level==='A'?'selected':''}>A</option><option ${r.level==='B'?'selected':''}>B</option><option ${r.level==='C'?'selected':''}>C</option></select></label><button class="button outline small" data-action="change-level" data-id="${r.id}">保存分级</button><button class="button outline small" data-action="edit-word" data-id="${r.id}">编辑词卡</button></div>`);
  }
  function intake(){intakeStage=null;intakeSource=null;showModal(`<div class="eyebrow">MAKE IT PERSONAL</div><h2>把不认识的词，放进来。</h2><p class="muted">粘贴聊天中你主动提交的陌生词，一行一个。短语保持整行；先纠错、去重，再确认分级与录入。</p><textarea id="intake-text" rows="9" placeholder="nutrition\nExacerbate Swelter\naffordable housing"></textarea><div class="notice">A：通用学术、雅思同义替换、写作口语与城市环境常用。B：专业低频、认读有用。C：暂时忽略。阅读推荐词只有你确认不认识后才入库。</div><button class="button" data-action="analyse-intake">分析与去重 →</button>`);}
  function analyseIntake(text){intakeStage=E.stageIntake(text??$('#intake-text').value,state.records,[...wordCards,...lessonPool().flatMap(l=>l.words.map(w=>({...w,source:{title:l.title,url:l.url,publisher:l.source,date:l.published}})))]);intakeStage.items=intakeStage.items.map(x=>{const suggestion=window.IELTS_CLASSIFY?.suggest(x.word,x.knownData)||{level:x.levelSuggested,reason:''};return {...x,levelSuggested:suggestion.level,classReason:suggestion.reason};});if(!intakeStage.items.length){toast('未发现英文词条，请一行一个粘贴词汇。');return;}showModal(`<div class="eyebrow">REVIEW BEFORE ADDING</div><h2>确认这次的词汇。</h2><p class="muted">${intakeStage.items.length} 个去重条目 · ${intakeStage.duplicates?.length||0} 个批内重复，${intakeStage.ignored?.length||0} 行说明已跳过。已有词仅记录重现；未见词需你确认陌生。</p><div class="intake-list">${intakeStage.items.map((x,i)=>`<div class="intake-row"><input type="checkbox" id="intake-check-${i}" ${x.existing?'checked':''} aria-label="确认 ${esc(x.word)} ${x.existing?'重现':'不认识'}"><div class="term"><strong>${esc(x.word)}</strong><div class="muted">${x.existing?'已在词库 · 提高优先级':x.knownData?'有词卡 · 确认不认识后收录':'新词 · 入库后请补充教学内容'}${x.correction?' · '+esc(x.original)+' → '+esc(x.word):''}<br>${esc(x.classReason||'')}</div></div><select aria-label="${esc(x.word)} 分级" id="intake-level-${i}">${['A','B','C'].map(l=>`<option ${l===(x.levelSuggested||x.level||'A')?'selected':''}>${l}</option>`).join('')}</select></div>`).join('')}</div><div class="notice">勾选表示：这个新词我确认不认识；已收录条目只记一次重现，不增加复习接触次数。建议分级可以调整。</div><button class="button" data-action="confirm-intake">确认收录 / 记录重现 →</button>`);}
  function confirmIntake(){const items=intakeStage.items.map((x,i)=>({...x,confirmed:$('#intake-check-'+i).checked,level:$('#intake-level-'+i).value,...(intakeSource?{source:intakeSource}:{})}));if(!items.some(x=>x.confirmed)){toast('请勾选你确认不认识或需要记录重现的词。');return;}state.records=E.confirmIntake(items,state.records,{date,batch:`${date} · 自主提交`});save();closeModal();libraryQuery='';libraryPage=0;location.hash='library';render();toast('已保存所选词汇。');}
  function editWord(id){const r=state.records.find(x=>x.id===id);showModal(`<div class="eyebrow">TEACHING NOTES</div><h2>补充 ${esc(r.word)} 的词卡</h2><div class="split"><label>英式 IPA<input id="edit-ipa" value="${esc(r.ipa)}"></label><label>词性<input id="edit-pos" value="${esc(r.pos)}"></label></div><label>中文核心义<input id="edit-meaning" value="${esc(r.meaning)}"></label><label>词族<input id="edit-family" value="${esc(r.family)}"></label><label>可靠记忆提示<input id="edit-memory" value="${esc(r.memory)}"></label><label>搭配，每行“英文 | 中文”<textarea id="edit-collocations" rows="3">${esc((r.collocations||[]).map(c=>c.en+' | '+c.zh).join('\n'))}</textarea></label><label>同义替换与区别<input id="edit-synonyms" value="${esc(r.synonyms)}"></label><label>英文例句<input id="edit-en" value="${esc(expEn(r))}"></label><label>例句中文<input id="edit-zh" value="${esc(expZh(r))}"></label><button class="button mt" data-action="save-word" data-id="${r.id}">保存词卡</button>`);}
  function selectedLesson(){return lessonPool().find(x=>x.id===currentLessonId)||dailyLesson();}
  function reading(){
    const l=selectedLesson();if(!l){main.innerHTML=heading('READING','阅读课程','打开课程档案，选择一篇文章继续练习。',`<button class="button" data-action="reading-archive">课程档案 →</button>`);return;}
    const result=state.readingState.results[date+'|'+l.id],formAnswers=readingDrafts[date+'|'+l.id]||result?.answers||{};
    main.innerHTML=window.IELTS_READING_UI.render({lesson:l,date,day:dayNo()||1,showAnswers,result,formAnswers,records:state.records,weaknesses:weaknesses(),completed:!!state.readingState.completed[l.id]});
    window.IELTS_READING_UI.bind(main,{onDraft:answers=>{readingDrafts[date+'|'+l.id]=answers;}});
    $('#reading-form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),answers=Object.fromEntries(l.questions.map(q=>[q.id,String(fd.get(q.id)||'').trim()]));if(Object.values(answers).some(x=>!x)){toast('还有题目未完成。');return;}delete readingDrafts[date+'|'+l.id];state.readingState.results[date+'|'+l.id]={answers,submittedAt:new Date().toISOString(),date,lessonId:l.id};save();showAnswers=true;reading();$('#answer-start')?.scrollIntoView({behavior:'smooth',block:'start'});};
  }
  function lessonAfterQuestions(){return "";}
  function archive(){showModal(`<div class="eyebrow">READING ARCHIVE</div><h2>已经核实的文章</h2><p class="muted">本站推荐记录不会重复；你以往聊天的文章历史未知，可在设置填写原文链接来排除。</p>${lessonPool().map(l=>`<div class="batch-row"><div class="batch-info"><strong>${esc(l.title)}</strong><p>${esc(l.source)} · ${l.published} · ${esc(l.topic)}</p></div><button class="button outline small" data-action="choose-lesson" data-id="${l.id}">打开</button></div>`).join('')}`);}
  function plan(){main.innerHTML=window.IELTS_PLAN_UI.render({state,date,engine:E});window.IELTS_PLAN_UI.bind(main,{onPreferences:p=>{state.preferences=S.validatePreferences({...state.preferences,...p});save();updateSidebar();}});}
  function settings(){const eligible=E.exportEligible(state.records,state.lastExcel,date);main.innerHTML=heading('KEEP YOUR PROGRESS','数据与设置','管理云端同步、学习偏好与备份。')+cloudPanel()+`<div class="split"><section class="card"><div class="eyebrow">VOCABULARY WORKBOOK</div><h2>Excel 词库</h2><p class="muted">A / B 工作表，包含英式 IPA、中文义、词族、搭配、同义替换、例句、学习与复习日期、错词标记及来源备注。</p><div class="notice ${eligible.allowed?'':'warn'}">最近整理：${state.lastExcel}<br>${esc(eligible.reason)}<br>推荐间隔 7 天 · 至少 5 天 · 至少 5 个新增词</div><button class="button" data-action="xlsx" ${!eligible.allowed?'disabled':''}>导出 .xlsx ↓</button><p class="safe-small">导出范围为本网站词库。可导出后再与旧 Excel 合并。</p></section><section class="card"><div class="eyebrow">YOUR DATA, AT HAND</div><h2>完整进度备份</h2><p class="muted">JSON 保留词库、接触次数、真实作答、错词加练、最近导出日和阅读推荐历史。换设备前建议下载。</p><div class="form-row"><button class="button" data-action="backup">下载 JSON 备份</button><button class="button outline" data-action="import-backup">恢复备份</button></div><input type="file" id="backup-file" accept="application/json,.json" hidden><div class="notice">恢复会使用备份中的进度。系统先校验内容，再提供确认；恢复后的记录会同步到当前账号。</div></section></div><div class="card mt"><div class="eyebrow">READING HISTORY</div><h2>排除以前推荐过的文章</h2><p class="muted">历史聊天推荐记录没有提供。粘贴原文 URL（一行一个），网站会排除这些文章，避免重复。</p><textarea id="excluded-urls" rows="3" placeholder="https://…">${esc(state.readingState.excluded.join('\n'))}</textarea><button class="button outline small mt" data-action="save-excluded">保存排除记录</button></div><div class="card mt"><div class="eyebrow">DAILY LESSON LIBRARY</div><h2>导入已核实的精读课程</h2><p class="muted">目前收录 ${lessonPool().length} 篇完整课程，每个学习日推荐一篇未推荐过的文章。课程用完会提示补充，不虚构近期文章。可导入采用本站字段的 JSON 课程包。</p><button class="button outline small" data-action="import-lesson">导入课程 JSON</button><input type="file" id="lesson-file" accept="application/json,.json" hidden><p class="safe-small">每日课程发布后会进入档案。也可以导入你自己的课程 JSON。</p></div>`;$('#backup-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>8000000)throw Error('备份过大，请检查文件。');const backup=E.validateBackup(await file.text());if(backup.customLessons!==undefined){if(!Array.isArray(backup.customLessons))throw Error('课程结构无效');validateLessons(backup.customLessons,true);}showModal(`<h2>恢复这个备份？</h2><p class="muted">备份包含 ${backup.records.length} 个词汇。恢复后，当前浏览器的学习进度会替换为备份；建议先下载当前备份。</p><div class="form-row"><button class="button outline" data-action="backup">下载当前备份</button><button class="button" id="restore-confirm">确认恢复</button></div>`);$('#restore-confirm').onclick=()=>{state.records=backup.records;state.lastExcel=backup.lastExcel;state.readingState=backup.readingState||emptyReading();state.customLessons=backup.customLessons||[];state.preferences=S.validatePreferences(backup.preferences);currentLessonId=null;showAnswers=false;reviewQueue=[];reviewIndex=0;save();closeModal();render();toast('备份已恢复。');};}catch(err){toast('备份未导入：'+err.message);}};
    $('#lesson-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>3000000)throw Error('课程文件过大');const data=JSON.parse(await f.text()),lessons=Array.isArray(data)?data:[data];validateLessons(lessons);state.customLessons.push(...lessons);save();render();toast('已导入课程，候选词没有自动入库。');}catch(err){toast('课程未导入：'+err.message);}};
  }
  function validateLessons(lessons,forRestore=false){const ids=new Set((forRestore?(window.READING_LESSONS||[]):lessonPool()).map(x=>x.id));for(const l of lessons){if(!/^[a-z0-9-]{1,80}$/.test(l.id)||ids.has(l.id)||typeof l.title!=='string'||!/^https:\/\//.test(l.url)||!/^\d{4}-\d{2}-\d{2}$/.test(l.published)||l.published>date||!/^\d{4}-\d{2}-\d{2}$/.test(l.verified)||l.verified>date)throw Error('缺少字段、日期无效或课程重复');ids.add(l.id);if(!['source','topic','difficulty','focus'].every(k=>typeof l[k]==='string')||!Number.isFinite(l.minutes))throw Error('文章元数据不完整');if(!Array.isArray(l.questions)||l.questions.length<3||l.questions.length>5||!l.questions.every(q=>['tfng','choice','fill'].includes(q.type)&&/^[a-z0-9-]{1,80}$/.test(q.id)&&['id','prompt','answer','translation','evidence','location','explanation','paraphrases','trap'].every(k=>typeof q[k]==='string')&&(!q.options||Array.isArray(q.options))))throw Error('题目或解析字段不完整');if(!Array.isArray(l.words)||l.words.length<15||l.words.length>20||!l.words.every(w=>['word','ipa','meaning','pos','family','context','synonyms'].every(k=>typeof w[k]==='string')&&Array.isArray(w.collocations)&&w.example?.en&&w.example?.zh))throw Error('词卡需 15–20 个并包含完整讲解');if(!['overview','structure','sentences','recall','writing','candidateWords'].every(k=>Array.isArray(l[k]))||!l.method?.en||!l.method?.zh)throw Error('精读栏目不完整');}}
  function speak(word){window.IELTS_AUDIO.play(word,info=>{if(info.kind==='loading')toast('加载英式发音…');if(info.kind==='recording')toast('英式词典录音');if(info.kind==='speech')toast('英式合成朗读');if(info.kind==='unavailable')toast('暂未找到英式录音，可查看 IPA 或词典。');});}
  function render(){const freshDate=E.today();if(freshDate!==date){date=freshDate;reviewQueue=[];reviewIndex=0;currentLessonId=null;showAnswers=false;}const route=location.hash.slice(1)||'today';const names={today:'今日学习',review:'间隔复习',library:'我的词库',reading:'每日精读',plan:'学习轨迹',settings:'数据与设置'};document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===route));$('#breadcrumb').innerHTML=`<a href="#today">学习工作台</a><span>/</span><select id="route-switch" aria-label="切换学习页面">${Object.entries(names).map(([key,name])=>`<option value="${key}" ${route===key?'selected':''}>${name}</option>`).join('')}</select>`;$('#route-switch').onchange=e=>{location.hash=e.target.value;};$('#top-date').textContent=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'}).format(new Date());$('#due-count').textContent=E.due(state.records,date).length||'';({today:dashboard,review,library,reading,plan,settings}[route]||dashboard)();updateSidebar();updateCloudStatus();if(storageProblem){main.insertAdjacentHTML('afterbegin',`<div class="notice warn">${esc(storageProblem)}</div>`);}}
  document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;switch(a){
    case'calendar-prev':calendarOffset--;dashboard();break;case'calendar-next':calendarOffset++;dashboard();break;case'calendar-day':openCalendarDay(b.dataset.date);break;
    case'library-letter':libraryLetter=b.dataset.letter;libraryPage=0;library();break;
    case'teach-choice':{const target=state.records.find(x=>x.id===reviewQueue[reviewIndex]?.id);const correct=b.dataset.value===target?.meaning;$('#teach-feedback').innerHTML=correct?'搭配中也是这个意思。试着读出下面的例句。':'再看一下词义和例句，然后重新选择。';document.querySelectorAll('[data-action=teach-choice]').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen');break;}
    case'teach-spelling':{const target=state.records.find(x=>x.id===reviewQueue[reviewIndex]?.id),input=$('#guided-spelling');$('#spelling-feedback').textContent=norm(input.value)===norm(target.word)?'拼写正确，接着练习搭配。':'对照 '+target.word+'，注意字母顺序，再试一次。';break;}
    case'auth-login':if(authClient)authClient.open();else toast('正在确认账号服务，请稍后再试。');break;
    case'auth-logout':await authClient?.logout();break;
    case'cloud-sync':if(authStatus.enabled&&!authStatus.authenticated){authClient?.open();break;}await cloudClient?.sync();break;case'cloud-conflict':showCloudConflict();break;case'cloud-resolve-local':await cloudClient?.resolveConflict('local');closeModal();break;case'cloud-resolve-remote':{backupRaw(state,'本机');await cloudClient?.resolveConflict('remote');closeModal();break;}case'cloud-backups':{const c=cloudClient?.getConflict();if(c){backupRaw(c.local,'本机');if(c.remote)backupRaw(c.remote,'云端');}break;}
    case'intake':intake();break;case'analyse-intake':analyseIntake();break;case'confirm-intake':confirmIntake();break;
    case'start-review':startReview();break;case'start-batch':startReview(b.dataset.batch);break;case'restart-review':reviewQueue=[];startReview();break;case'exit-review':reviewQueue=[];review();break;
    case'confirm-study':recordReview('studied');break;case'correct-review':recordReview('correct');break;case'wrong-review':recordReview('wrong');break;
    case'recall-en-zh':recallDirection='en-zh';reviewAnswer='';review();break;case'recall-zh-en':recallDirection='zh-en';reviewAnswer='';review();break;
    case'reveal-review':reviewAnswer=$('#review-answer').value;$('#review-reveal').hidden=false;b.disabled=true;break;
    case'speak':speak(b.dataset.word);break;case'word-detail':wordDetail(b.dataset.id);break;case'library-filter':libraryLevel=b.dataset.level;libraryPage=0;library();break;case'prev-page':libraryPage--;library();break;case'next-page':libraryPage++;library();break;
    case'change-level':{const r=state.records.find(x=>x.id===b.dataset.id);state.records=state.records.map(x=>x.id===r.id?Object.assign(E.setLevel(r,$('#detail-level').value),{levelLocked:true}):x);save();closeModal();render();toast('已保存分级。');break;}
    case'edit-word':editWord(b.dataset.id);break;
    case'save-word':{const r=state.records.find(x=>x.id===b.dataset.id);r.ipa=$('#edit-ipa').value.trim();r.pos=$('#edit-pos').value.trim();r.meaning=$('#edit-meaning').value.trim();r.family=$('#edit-family').value.trim();r.memory=$('#edit-memory').value.trim();r.synonyms=$('#edit-synonyms').value.trim();r.collocations=$('#edit-collocations').value.split('\n').filter(x=>x.includes('|')).map(x=>({en:x.split('|')[0].trim(),zh:x.split('|').slice(1).join('|').trim()}));r.example={en:$('#edit-en').value.trim(),zh:$('#edit-zh').value.trim()};r.exampleEn=r.example.en;r.exampleZh=r.example.zh;r.needsContent=!(r.ipa&&r.meaning&&r.pos&&r.example.en&&r.example.zh&&r.collocations.length>=2);save();closeModal();render();toast(r.needsContent?'已保存，完整教学仍需 IPA、词义、词性、两条搭配与双语例句。':'完整词卡已保存。');break;}
    case'reveal-reading':{const l=selectedLesson();const data=new FormData($('#reading-form'));readingDrafts[date+'|'+l.id]=Object.fromEntries(l.questions.map(q=>[q.id,String(data.get(q.id)||'').trim()]));}showAnswers=true;reading();$('#answer-start').scrollIntoView({behavior:'smooth'});break;case'reading-archive':archive();break;case'choose-lesson':currentLessonId=b.dataset.id;showAnswers=false;closeModal();location.hash='reading';reading();window.scrollTo(0,0);break;
    case'intake-candidates':{const selected=[...document.querySelectorAll('.candidate-check:checked')].map(x=>x.value);if(!selected.length){toast('先勾选确认不认识或重复出现的词。');break;}const current=selectedLesson();intakeSource={title:current.title,url:current.url,publisher:current.source,date:current.published};analyseIntake(selected.join('\n'));break;}
    case'copy-candidates':{const text=$('#candidate-export').textContent;try{await navigator.clipboard.writeText(text);toast('候选清单已复制，请按陌生词筛选录入。');}catch{const range=document.createRange();range.selectNodeContents($('#candidate-export'));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);toast('已选中清单，请手动复制。');}break;}
    case'anki':{const l=selectedLesson();const tsv=l.words.map(w=>[w.word+' '+w.ipa,w.meaning+'<br>'+w.collocations.map(c=>c.en+'：'+c.zh).join('<br>')+'<br>'+w.example.en+'<br>'+w.example.zh].join('\t')).join('\n');download(tsv,`循词-Anki-${date}.tsv`,'text/tab-separated-values;charset=utf-8');toast('Anki 卡已下载；导入时选择制表符和允许 HTML。');break;}
    case'complete-reading':state.readingState.completed[selectedLesson().id]=date;save();toast('已记录精读完成；词汇掌握状态没有自动改变。');reading();break;
    case'xlsx':{const eligibility=E.exportEligible(state.records,state.lastExcel,date);if(!eligibility.allowed){toast(eligibility.reason);break;}download(window.exportVocabularyXlsx(state.records),`循词-IELTS7-词库-${date}.xlsx`);state.lastExcel=date;save();settings();toast('A / B 工作表已导出，范围为本站确认词库。');break;}
    case'backup':{const data=E.makeBackup(state.records,{lastExcel:state.lastExcel,readingState:state.readingState});data.customLessons=state.customLessons;data.preferences=state.preferences;download(JSON.stringify(data,null,2),`循词-完整进度-${date}.json`,'application/json');break;}
    case'import-backup':$('#backup-file').click();break;case'import-lesson':$('#lesson-file').click();break;
    case'save-excluded':{const urls=$('#excluded-urls').value.split('\n').map(x=>x.trim()).filter(Boolean);if(urls.some(x=>!/^https?:\/\//.test(x))){toast('请每行输入一个完整文章 URL。');break;}state.readingState.excluded=[...new Set(urls)];const current=lessonPool().find(x=>x.id===state.readingState.assignments[date]);if(current&&urls.includes(current.url)){delete state.readingState.assignments[date];currentLessonId=null;showAnswers=false;}save();toast('已保存排除记录。');break;}
  }});
  setInterval(()=>{if(!document.hidden&&E.today()!==date)render();},30000);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden&&E.today()!==date)render();});
  window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});

  function examNotes(r){const note=window.IELTS_EXAM_NOTES?.[r.word];const senses=r.senses||note?.senses;if(!note&&!senses)return '';return `<div class="exam-notes"><h4>IELTS 用法</h4>${senses?(senses.map(x=>Array.isArray(x)?`<div class="sense"><strong>${esc(x[0])}</strong><span>${esc(x[1])}</span><small>${esc(x[2])}</small></div>`:`<div class="sense"><strong>${esc(x.meaning)}</strong><span>${esc(x.en)}</span><small>${esc(x.zh)}</small></div>`).join('')):''}${note?.tip?`<p>${esc(note.tip)}</p>`:''}</div>`;}
  function teachingInteraction(r){if(r.level==='B'||r.needsContent)return '';const others=state.records.filter(x=>x.id!==r.id&&x.meaning&&x.level==='A').slice(0,2).map(x=>x.meaning);const opts=[r.meaning,...others].sort((a,b)=>a.localeCompare(b,'zh'));return `<section class="teaching-interaction"><h3>理解练习</h3><p>在 <strong>${esc(r.collocations?.[0]?.en||r.word)}</strong> 中，${esc(r.word)} 的意思是：</p><div class="meaning-choices">${opts.map(v=>`<button data-action="teach-choice" data-value="${esc(v)}">${esc(v)}</button>`).join('')}</div><p id="teach-feedback" class="practice-feedback"></p><details><summary>对照词形拼一次</summary><div class="guided-spelling"><span>${esc(r.word)}</span><input id="guided-spelling" autocomplete="off" spellcheck="false" aria-label="对照拼写 ${esc(r.word)}"><button class="button outline small" data-action="teach-spelling">检查</button></div><p id="spelling-feedback" class="practice-feedback"></p></details></section>`;}
  function openCalendarDay(day){const id=state.readingState.assignments[day],l=lessonPool().find(x=>x.id===id),learned=state.records.filter(r=>r.reviewHistory?.some(h=>h.date===day));showModal(`<div class="eyebrow">学习日历</div><h2>${day}</h2>${l?`<div class="calendar-article"><small>${esc(l.topic)}</small><h3>${esc(l.title)}</h3><p class="title-zh">${esc(l.titleZh||l.article?.titleZh||'')}</p><button class="button" data-action="choose-lesson" data-id="${l.id}">回看文章与练习 →</button></div>`:'<p class="muted">这一天没有精读记录。</p>'}<h3>词汇学习 · ${learned.length} 词</h3><div class="calendar-word-list">${learned.map(r=>`<button data-action="word-detail" data-id="${r.id}"><strong>${esc(r.word)}</strong><span>${esc(r.meaning)}</span></button>`).join('')||'<p class="muted">暂无词汇记录。</p>'}</div>`);}
  function makeInitialState(){return {records:E.seed(window.VOCAB_HISTORY||[],window.VOCAB_NEW||[]),lastExcel:E.today(),readingState:emptyReading(),customLessons:[],preferences:S.validatePreferences()};}
  function pristine(data){const initial=makeInitialState();return S.fingerprint({...data,readingState:emptyReading()})===S.fingerprint(initial)&&!Object.keys(data.readingState.results||{}).length&&!Object.keys(data.readingState.completed||{}).length;}
  function updateSidebar(){const node=$('#sidebar-progress');if(!node)return;const words=state.records.filter(r=>r.reviewHistory?.some(h=>h.date===date)).length;const lesson=state.readingState.assignments[date],read=lesson&&state.readingState.completed[lesson]?1:0;node.innerHTML=`<a href="#plan"><span>今日安排</span><strong>${words}<small> / ${state.preferences.dailyReviewLimit} 词</small></strong><div class="sidebar-meter"><i style="width:${Math.min(100,words/state.preferences.dailyReviewLimit*100)}%"></i></div><p>精读 ${read} / 1 篇 <b>查看计划 →</b></p></a>`;}
  function accountControls(){return authStatus.enabled?`<button class="button outline" data-action="auth-login">${authStatus.authenticated?'管理邮箱账号':'邮箱登录'}</button>${authStatus.authenticated?'<button class="text-button" data-action="auth-logout">退出登录</button>':''}`:`<a class="button outline" href="/signin-with-chatgpt?return_to=%2F" target="_top">ChatGPT 登录</a><button class="button outline" data-action="auth-login">邮箱登录</button>${authStatus.status==='disabled'?'<span class="muted">邮箱登录待启用</span>':''}`;}
  function cloudPanel(){return `<section class="card cloud-panel" id="cloud-panel"><div class="eyebrow">ACCOUNT & SYNC</div><h2>云端学习记录</h2><div id="cloud-panel-status"></div><div class="form-row"><button class="button" data-action="cloud-sync">立即同步</button><span id="auth-account-controls">${accountControls()}</span><button class="button outline" data-action="cloud-conflict" id="cloud-conflict-button" hidden>处理版本冲突</button></div><p class="muted">同一账号在不同设备共享词库、作答、复习安排和课程记录。断网时先保存在本机，连接恢复后继续同步。</p></section>`;}
  function updateCloudStatus(){const labels={loading:'连接中',syncing:'同步中',synced:'已同步',offline:'等待连接',conflict:'版本冲突',unauthorized:'需要登录',unavailable:'本机保存'};const label=labels[cloudStatus.status]||'连接中';for(const selector of ['#sync-label','#sidebar-sync-label']){const n=$(selector);if(n)n.textContent=label;}const badge=$('#sync-badge');if(badge)badge.dataset.status=cloudStatus.status;const panel=$('#cloud-panel-status');if(panel)panel.innerHTML=`<strong>${esc(label)}</strong>${cloudStatus.user?.email?`<span>${esc(cloudStatus.user.email)}</span>`:''}${cloudStatus.updatedAt?`<small>最近同步 ${new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(cloudStatus.updatedAt))}</small>`:''}${!['synced','syncing','loading'].includes(cloudStatus.status)?`<p>${esc(cloudStatus.message)}</p>`:''}`;const conflict=$('#cloud-conflict-button');if(conflict)conflict.hidden=cloudStatus.status!=='conflict';}
  function backupRaw(data,label){download(JSON.stringify(S.serialize(data),null,2),`循词-${label}-${date}.json`,'application/json');}
  function showCloudConflict(){const c=cloudClient?.getConflict();if(!c){toast('当前没有版本冲突。');return;}showModal(`<div class="eyebrow">SYNC</div><h2>选择要保留的学习记录</h2><p>两台设备同时改了同一条记录，需要选择一个版本。可以先下载双方备份。</p><div class="conflict-summary"><div><strong>本机版本</strong><p>${c.local?.records?.length||0} 词</p></div><div><strong>云端版本</strong><p>${c.remote?.records?.length||0} 词</p></div></div><div class="form-row"><button class="button outline" data-action="cloud-backups">下载两份备份</button><button class="button" data-action="cloud-resolve-remote">采用云端版本</button><button class="button outline" data-action="cloud-resolve-local">用本机版本更新云端</button></div>`);}
  async function loadOnlineContent(){try{cloudLessons=await window.IELTS_CLOUD.loadLessons();if((location.hash||'#today')==='#today')dashboard();}catch{}try{const r=await fetch('/api/word-cards',{credentials:'same-origin',cache:'no-store'});if(r.ok){const data=await r.json();if(Array.isArray(data.cards)){wordCards=data.cards;let changed=false;state.records=state.records.map(r=>{const card=wordCards.find(c=>E.normalizeWord(c.word)===r.word);if(!card||!r.needsContent)return r;changed=true;let next={...r,...card,id:r.id,word:r.word,firstSeen:r.firstSeen,lastReview:r.lastReview,nextReview:r.nextReview,contacts:r.contacts,contactDates:r.contactDates,reviewHistory:r.reviewHistory,errors:r.errors,extraReviews:r.extraReviews,status:r.status,origins:r.origins,needsContent:false};if(r.levelLocked)next.level=r.level;else next=E.setLevel(next,card.level||r.level);return next;});if(changed){save();render();}}}}catch{}}
  function pauseCloud(){cloudClient?.stop();cloudClient=null;cloudStatus={status:'loading',message:'正在确认登录账号',user:null};updateCloudStatus();}
  function startCloud(){cloudClient?.stop();cloudClient=window.IELTS_CLOUD.create({getState:()=>state,setState:next=>{const form=$('#reading-form'),l=selectedLesson();if(form&&l)readingDrafts[date+'|'+l.id]=Object.fromEntries(new FormData(form));state=S.validateState(next);save(true);render();},makeInitialState,isPristine:pristine,onStatus:status=>{cloudStatus=status;updateCloudStatus();},onConflict:()=>{updateCloudStatus();toast('两台设备的记录有冲突，请在数据与设置处理。');}});cloudClient.start();loadOnlineContent();}
  function resumeCloud(){if(authStatus.enabled&&!authStatus.authenticated){pauseCloud();cloudStatus={status:'unauthorized',message:'登录邮箱后同步学习记录。本机进度已保留。',user:null};updateCloudStatus();loadOnlineContent();}else startCloud();}
  async function startAccount(){if(!window.IELTS_AUTH){startCloud();return;}authClient=window.IELTS_AUTH.create({onBeforeChange:pauseCloud,onStatus:status=>{authStatus=status;const controls=$('#auth-account-controls');if(controls)controls.innerHTML=accountControls();const button=$('#account-button');if(button)button.textContent=status.enabled?'邮箱账号':'账号';},onChange:()=>{authStatus=authClient.getStatus();if(authBootReady)resumeCloud();},onBackup:backups=>{for(const [name,snapshot]of Object.entries(backups||{})){if(snapshot?.state)backupRaw(snapshot.state,name==='legacy'?'原账号':'邮箱账号');}}});try{authStatus=await authClient.init();authBootReady=true;resumeCloud();}catch{authBootReady=true;cloudStatus={status:'unavailable',message:'账号服务暂时无法连接，本机进度已保留。',user:null};updateCloudStatus();loadOnlineContent();}}

  render();
  startAccount();
  const emailResult=new URL(location.href).searchParams.get('email-login');
  if(emailResult==='success'||emailResult==='expired'){toast(emailResult==='success'?'邮箱登录成功，正在连接学习记录。':'登录链接已失效，或不是在发起登录的浏览器中打开。请重新获取链接。');const url=new URL(location.href);url.searchParams.delete('email-login');history.replaceState(null,'',url.pathname+url.search+url.hash);}
})();
